#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int x;
    struct Node *next;
} Node;

int main() {
    Node *head = NULL;

    for (int i = 3; i >= 1; i--) {
        Node *p = (Node *)malloc(sizeof(Node));
        p->x = i;
        p->next = head;
        head = p;
    }

    for (Node *cur = head; cur != NULL; cur = cur->next) {
        printf("%d\n", cur->x);
    }

    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int x;
    struct Node *next;
} Node;

int main() {
    Node *head = NULL;

    for (int i = 1; i <= 3; i++) {
        Node *p = (Node *)malloc(sizeof(Node));
        p->x = i * 10;
        p->next = head;
        head = p;
    }

    Node *old = head;
    head = head->next;
    free(old);

    printf("%d\n", head->x);

    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}

